OPERATIONS = {
    'add': lambda a, b: a + b,
    'sub': lambda a, b: a - b,
    'mul': lambda a, b: a * b,
    'max': lambda a, b: max(a, b),
}

n = int(input())
for _ in range(n):
    op, a, b = input().split()
    strategy = OPERATIONS.get(op)
    if strategy is None:
        print(f'unknown: {op}')
    else:
        print(strategy(int(a), int(b)))

