def bump(version, kind):
    major, minor, patch = (int(p) for p in version.split('.'))
    if kind == 'major':
        return f'{major + 1}.0.0'
    if kind == 'minor':
        return f'{major}.{minor + 1}.0'
    return f'{major}.{minor}.{patch + 1}'


version = input().strip()
n = int(input())
for _ in range(n):
    version = bump(version, input().strip())
    print(version)
